import csv

ts_ids = {
    "Core_bottom": "134c4f67-a2ef-5cd4-b03a-f18a5601c587",
    "Perimeter_mid_ZN_4": "aae47278-33aa-5890-bc25-fe8f2730710b",
    "Perimeter_top_ZN_3": "66009ccf-dd88-5be4-87fd-ed38ec990e48"
}

target_date = "2018-04-13"
energy_sums = {}

with open(VALUES_CSV, 'r') as f:
    reader = csv.reader(f)
    next(reader) # skip header
    for row in reader:
        ts_id, timestamp, value = row
        if timestamp.startswith(target_date):
            for zone, zid in ts_ids.items():
                if ts_id == zid:
                    energy_sums[zone] = energy_sums.get(zone, 0) + float(value)

print(energy_sums)
